// Real Japanese Acoustic Sound & Lowkey Ambient BGM Engine (Web Audio API)
// Plays:
// 1. Real Studio Japanese Chill / Lowkey Background Music (Minamo, Minamo 2, Shizima 2 by PeriTune) with seamless crossfade loop
// 2. Real Hanafuda card snaps ("Pachin!"), Koto pentatonic chimes, Kabuki Hyoshigi clappers, and Taiko drums.

export const BGM_TRACKS = [
  {
    id: 'minamo',
    name: '💧 Mặt Nước Tĩnh Lặng',
    subtitle: 'Đàn Koto gảy thưa & Piano mộc (Minamo)',
    url: './public/assets/bgm/minamo.mp3?v=1'
  },
  {
    id: 'minamo2',
    name: '🌊 Hồ Đêm Gợn Sóng',
    subtitle: 'Koto & Sáo trúc Ambient sương đêm (Minamo 2)',
    url: './public/assets/bgm/minamo2.mp3?v=1'
  },
  {
    id: 'shizima2',
    name: '🎋 Tĩnh Mịch Rừng Khuya',
    subtitle: 'Koto trầm & Sáo Shakuhachi Thiền (Shizima 2)',
    url: './public/assets/bgm/shizima2.mp3?v=1'
  }
];

const BGM_ENABLED_STORAGE_KEY = 'hanakoi_bgm_enabled';
const BGM_TRACK_STORAGE_KEY = 'hanakoi_bgm_track_id';
const SFX_ENABLED_STORAGE_KEY = 'hanakoi_sfx_enabled';

// File ghi âm nhạc cụ Nhật Bản & lá bài thật miễn phí bản quyền (CC0 1.0 - Kenney & Versilian VCSL), 1–14KB/file
export const CARD_SFX_FILES = {
  shuffle: './public/assets/sfx/card_shuffle.mp3?v=4',
  deal: './public/assets/sfx/card_deal.mp3?v=4',
  flip: './public/assets/sfx/card_flip.mp3?v=4',
  slap: './public/assets/sfx/card_slap.mp3?v=4',
  month: './public/assets/sfx/month_taiko.mp3?v=4',
  yaku: './public/assets/sfx/yaku_tane.mp3?v=4',
  yaku_kasu: './public/assets/sfx/yaku_kasu.mp3?v=4',
  yaku_tanzaku: './public/assets/sfx/yaku_tanzaku.mp3?v=4',
  yaku_tane: './public/assets/sfx/yaku_tane.mp3?v=4',
  yaku_hikari: './public/assets/sfx/yaku_hikari.mp3?v=4',
  koikoi: './public/assets/sfx/koikoi_hyoshigi.mp3?v=4',
  click: './public/assets/sfx/ui_click.mp3?v=4',
  coin: './public/assets/sfx/coin_reward.mp3?v=4'
};

// Nhúng sẵn dữ liệu nhị phân Base64 của toàn bộ file MP3 CC0 để giải mã tức thì ở 0ms (kể cả khi mở qua file:// hoặc mạng chậm)
const CARD_SFX_BASE64 = {
  shuffle: '',
  deal: '',
  flip: '',
  slap: '',
  month: '',
  yaku: '',
  yaku_kasu: '',
  yaku_tanzaku: '',
  yaku_tane: '',
  yaku_hikari: '',
  koikoi: '',
  click: '',
  coin: ''
};

function base64ToArrayBuffer(b64) {
  const bin = atob(b64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = bin.charCodeAt(i);
  }
  return bytes.buffer;
}

function readAudioPref(key) {
  try {
    return localStorage.getItem(key) !== '0';
  } catch {
    return true;
  }
}

function writeAudioPref(key, enabled) {
  try {
    localStorage.setItem(key, enabled ? '1' : '0');
  } catch {
    // Ignore storage errors
  }
}

class SoundEngine {
  constructor() {
    this.ctx = null;
    this.iosUnlocked = false;
    // Nhạc nền (BGM) và hiệu ứng âm thanh (SFX + giọng nhân vật) bật/tắt độc lập
    this.bgmEnabled = readAudioPref(BGM_ENABLED_STORAGE_KEY);
    this.sfxEnabled = readAudioPref(SFX_ENABLED_STORAGE_KEY);
    this.bgmPlaying = false;
    this.bgmTimer = null;
    this.bgmStep = 0;
    this.currentTrackIndex = 0;
    try {
      const savedId = localStorage.getItem(BGM_TRACK_STORAGE_KEY);
      if (savedId) {
        const idx = BGM_TRACKS.findIndex((t) => t.id === savedId);
        if (idx >= 0) this.currentTrackIndex = idx;
      }
    } catch {
      // Ignore storage errors
    }
    this.bgmVolume = 0.36;

    // Audio bus & real BGM track state
    this.bgmMasterGain = null;
    this.bgmBuffers = {};
    this.bgmLoopMeta = {};
    this.bgmLoadPromises = {};
    this.bgmSourceNode = null;
    this.bgmHtmlAudio = null;
    this.bgmRequestToken = 0;

    // Web Audio decoded buffers & raw ArrayBuffers cho 9 tiếng CC0 (Nhóm 1 + Nhóm 2)
    this.sfxRawBuffers = {};
    this.sfxBuffers = {};
    this.sfxOffsets = {};
    this.sfxDecodePromises = {};
    this.activeSfxSources = new Set();
    this.dealTimers = [];

    this.preloadCardSfxFiles();
  }

  // Tắt hết cả nhạc nền lẫn SFX
  get muted() {
    return !this.bgmEnabled && !this.sfxEnabled;
  }

  ensureContext(resumeNow = true) {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();
        this.setupBgmBus(this.ctx);
        this.decodePendingCardSfx();
      }
    }
    if (resumeNow && this.ctx && (this.ctx.state === 'suspended' || this.ctx.state === 'interrupted')) {
      this.ctx.resume().catch(() => {});
    }
    return this.ctx;
  }

  /**
   * Mở khóa Web Audio trên iOS Safari ngay trong cử chỉ chạm đầu tiên (touchstart/touchend/pointerdown)
   */
  unlockAudio() {
    const ctx = this.ensureContext(true);
    if (!ctx) return;
    if (!this.iosUnlocked) {
      try {
        const silentBuf = ctx.createBuffer(1, 1, 22050);
        const src = ctx.createBufferSource();
        src.buffer = silentBuf;
        src.connect(ctx.destination);
        src.start(0);
        this.iosUnlocked = true;
      } catch {
        // Ignore
      }
    }
    this.decodePendingCardSfx();
  }

  /**
   * Nạp ngay dữ liệu nhị phân 9 file MP3 CC0 từ bộ nhớ đệm (hoạt động cả trên file:// và HTTP)
   * và giải mã sang AudioBuffer ngay khi trang vừa tải xong.
   */
  preloadCardSfxFiles() {
    if (typeof window === 'undefined') return;
    Object.entries(CARD_SFX_BASE64).forEach(([key, b64]) => {
      try {
        this.sfxRawBuffers[key] = base64ToArrayBuffer(b64);
      } catch {
        // Ignore
      }
    });
    // Tạo sẵn AudioContext (ở trạng thái chờ) để giải mã toàn bộ 9 MP3 sang AudioBuffer ngay lập tức
    this.ensureContext(false);
    this.decodePendingCardSfx();

    // Nếu chạy qua HTTP/HTTPS, vẫn hỗ trợ đồng bộ file mới từ CARD_SFX_FILES
    if (typeof fetch === 'function' && window.location && window.location.protocol !== 'file:') {
      Object.entries(CARD_SFX_FILES).forEach(([key, url]) => {
        fetch(url)
          .then((res) => (res.ok ? res.arrayBuffer() : Promise.reject(new Error(String(res.status)))))
          .then((buf) => {
            if (buf && buf.byteLength > 0) {
              this.sfxRawBuffers[key] = buf;
              if (!this.sfxBuffers[key]) {
                this.decodeSingleCardSfx(key);
              }
            }
          })
          .catch(() => {});
      });

      if (this.bgmEnabled) {
        this.loadBgmTrackBuffer(this.getCurrentTrack());
      }
    }
  }

  decodePendingCardSfx() {
    if (!this.ctx) return;
    Object.keys(this.sfxRawBuffers).forEach((key) => {
      if (!this.sfxBuffers[key] && !this.sfxDecodePromises[key]) {
        this.decodeSingleCardSfx(key);
      }
    });
  }

  decodeSingleCardSfx(key) {
    if (this.sfxBuffers[key]) return Promise.resolve(this.sfxBuffers[key]);
    if (this.sfxDecodePromises[key]) return this.sfxDecodePromises[key];
    const ctx = this.ensureContext(false);
    const raw = this.sfxRawBuffers[key];
    if (!ctx || !raw) return Promise.resolve(null);

    const copy = raw.slice(0);
    const p = new Promise((resolve) => {
      const onDecoded = (audioBuffer) => {
        delete this.sfxDecodePromises[key];
        if (!audioBuffer) {
          resolve(null);
          return;
        }
        this.sfxBuffers[key] = audioBuffer;
        // Tìm đúng mẫu bắt đầu có tín hiệu để bỏ khoảng trễ đầu frame MP3 (~26ms) -> phát tức thì 0ms
        const ch = audioBuffer.getChannelData(0);
        let firstIdx = 0;
        for (let i = 0; i < ch.length; i++) {
          if (Math.abs(ch[i]) > 0.018) {
            firstIdx = Math.max(0, i - Math.floor(audioBuffer.sampleRate * 0.002));
            break;
          }
        }
        this.sfxOffsets[key] = firstIdx / audioBuffer.sampleRate;
        resolve(audioBuffer);
      };
      const onError = () => {
        delete this.sfxDecodePromises[key];
        resolve(null);
      };
      try {
        const ret = ctx.decodeAudioData(copy, onDecoded, onError);
        if (ret && typeof ret.then === 'function') {
          ret.then(onDecoded, onError);
        }
      } catch {
        onError();
      }
    });
    this.sfxDecodePromises[key] = p;
    return p;
  }

  // Context dành cho SFX: trả về null khi SFX đang tắt
  sfxContext() {
    if (!this.sfxEnabled) return null;
    return this.ensureContext();
  }

  /**
   * Master gain bus for real BGM tracks
   */
  setupBgmBus(ctx) {
    this.bgmMasterGain = ctx.createGain();
    this.bgmMasterGain.gain.setValueAtTime(this.bgmVolume, ctx.currentTime);
    this.bgmMasterGain.connect(ctx.destination);
  }

  _stopCurrentBgmNodes(fadeOutSec = 0.25) {
    if (this.bgmTimer) {
      clearInterval(this.bgmTimer);
      this.bgmTimer = null;
    }
    if (this.bgmSourceNode) {
      const oldSrc = this.bgmSourceNode;
      this.bgmSourceNode = null;
      try {
        oldSrc.onended = null;
        oldSrc.stop();
        oldSrc.disconnect();
      } catch {
        // Ignore
      }
    }
    if (this.bgmHtmlAudio) {
      const oldAudio = this.bgmHtmlAudio;
      this.bgmHtmlAudio = null;
      try {
        oldAudio.pause();
        oldAudio.src = '';
      } catch {
        // Ignore
      }
    }
    if (fadeOutSec <= 0 && this.ctx && this.bgmMasterGain) {
      const now = this.ctx.currentTime;
      this.bgmMasterGain.gain.cancelScheduledValues(now);
      this.bgmMasterGain.gain.setValueAtTime(this.bgmVolume, now);
    }
  }

  // Tắt dần bus BGM hiện tại rồi ngắt hẳn, tạo bus mới (dùng khi đổi bài)
  replaceBgmBus() {
    this.bgmRequestToken++;
    this._stopCurrentBgmNodes(0);
    const ctx = this.ensureContext();
    if (!ctx) return;
    const oldMaster = this.bgmMasterGain;
    if (oldMaster) {
      const now = ctx.currentTime;
      oldMaster.gain.cancelScheduledValues(now);
      oldMaster.gain.setValueAtTime(oldMaster.gain.value, now);
      oldMaster.gain.linearRampToValueAtTime(0.0001, now + 0.22);
      setTimeout(() => {
        try { oldMaster.disconnect(); } catch { /* Ignore */ }
      }, 280);
    }
    this.setupBgmBus(ctx);
    this.bgmPlaying = false;
  }

  getCurrentTrack() {
    return BGM_TRACKS[this.currentTrackIndex] || BGM_TRACKS[0];
  }

  cycleTrack() {
    this.currentTrackIndex = (this.currentTrackIndex + 1) % BGM_TRACKS.length;
    this.bgmStep = 0;
    this.bgmEnabled = true;
    writeAudioPref(BGM_ENABLED_STORAGE_KEY, true);
    try {
      const track = this.getCurrentTrack();
      if (track && track.id) {
        localStorage.setItem(BGM_TRACK_STORAGE_KEY, track.id);
      }
    } catch {
      // Ignore storage errors
    }
    this.replaceBgmBus();
    this.startBgm();
    this.playButtonClick();
    return this.getCurrentTrack();
  }

  toggleBgm() {
    this.bgmEnabled = !this.bgmEnabled;
    writeAudioPref(BGM_ENABLED_STORAGE_KEY, this.bgmEnabled);
    if (this.bgmEnabled) {
      this.startBgm();
    } else {
      this.stopBgm();
    }
    return this.bgmEnabled;
  }

  stopActiveSfx() {
    if (this.dealTimers && this.dealTimers.length > 0) {
      this.dealTimers.forEach((t) => clearTimeout(t));
      this.dealTimers = [];
    }
    if (this.activeSfxSources && this.activeSfxSources.size > 0) {
      this.activeSfxSources.forEach((src) => {
        try {
          src.stop();
        } catch {
          // Ignore
        }
      });
      this.activeSfxSources.clear();
    }
  }

  toggleSfx() {
    this.sfxEnabled = !this.sfxEnabled;
    writeAudioPref(SFX_ENABLED_STORAGE_KEY, this.sfxEnabled);
    if (!this.sfxEnabled) {
      this.stopActiveSfx();
      if (window.speechSynthesis) {
        try {
          window.speechSynthesis.cancel();
        } catch {
          // Ignore
        }
      }
    }
    return this.sfxEnabled;
  }

  /**
   * Chuẩn bị vùng lặp Crossfade mượt (2.4 giây) trực tiếp trên AudioBuffer
   * để khi AudioBufferSourceNode quay vòng từ loopEnd về loopStart sẽ liền mạch 100% không khựng.
   */
  _prepareSeamlessLoopMeta(audioBuffer) {
    const sr = audioBuffer.sampleRate;
    const ch0 = audioBuffer.getChannelData(0);
    const len = ch0.length;

    let firstIdx = 0;
    for (let i = 0; i < len; i++) {
      if (Math.abs(ch0[i]) > 0.0025) {
        firstIdx = i;
        break;
      }
    }

    let lastIdx = len - 1;
    for (let i = len - 1; i > firstIdx; i--) {
      if (Math.abs(ch0[i]) > 0.0025) {
        lastIdx = i;
        break;
      }
    }

    const activeLen = lastIdx - firstIdx;
    const fadeSamples = Math.min(Math.floor(sr * 2.4), Math.floor(activeLen * 0.15));

    if (fadeSamples > 1024 && activeLen > fadeSamples * 3) {
      const numChannels = audioBuffer.numberOfChannels;
      const tailStart = lastIdx - fadeSamples;
      for (let c = 0; c < numChannels; c++) {
        const data = audioBuffer.getChannelData(c);
        for (let i = 0; i < fadeSamples; i++) {
          // Cosine equal-feel crossfade: trộn đuôi bài vào đầu bài
          const t = 0.5 - 0.5 * Math.cos((Math.PI * i) / fadeSamples);
          const headVal = data[firstIdx + i];
          const tailVal = data[tailStart + i];
          data[firstIdx + i] = headVal * t + tailVal * (1 - t);
        }
      }
      return {
        loopStart: firstIdx / sr,
        loopEnd: tailStart / sr
      };
    }

    return {
      loopStart: firstIdx / sr,
      loopEnd: Math.max(firstIdx / sr + 1, lastIdx / sr)
    };
  }

  /**
   * Tải và giải mã file MP3 nhạc nền thật sang AudioBuffer (có bộ nhớ đệm)
   */
  loadBgmTrackBuffer(track) {
    if (!track || !track.url) return Promise.resolve(null);
    if (this.bgmBuffers[track.id]) {
      return Promise.resolve(this.bgmBuffers[track.id]);
    }
    if (this.bgmLoadPromises[track.id]) {
      return this.bgmLoadPromises[track.id];
    }
    if (typeof fetch !== 'function' || (window.location && window.location.protocol === 'file:')) {
      return Promise.resolve(null);
    }

    const ctx = this.ensureContext(false);
    if (!ctx) return Promise.resolve(null);

    const p = fetch(track.url)
      .then((res) => (res.ok ? res.arrayBuffer() : Promise.reject(new Error(String(res.status)))))
      .then(
        (rawBuf) =>
          new Promise((resolve) => {
            const onDecoded = (decoded) => {
              delete this.bgmLoadPromises[track.id];
              if (decoded) {
                this.bgmBuffers[track.id] = decoded;
                this.bgmLoopMeta[track.id] = this._prepareSeamlessLoopMeta(decoded);
              }
              resolve(decoded || null);
            };
            const onError = () => {
              delete this.bgmLoadPromises[track.id];
              resolve(null);
            };
            try {
              const ret = ctx.decodeAudioData(rawBuf, onDecoded, onError);
              if (ret && typeof ret.then === 'function') {
                ret.then(onDecoded, onError);
              }
            } catch {
              onError();
            }
          })
      )
      .catch(() => {
        delete this.bgmLoadPromises[track.id];
        return null;
      });

    this.bgmLoadPromises[track.id] = p;
    return p;
  }

  _startHtmlAudioFallback(track, token) {
    if (!this.bgmEnabled || token !== this.bgmRequestToken || !track || !track.url) return;
    try {
      this._stopCurrentBgmNodes(0);
      const audio = new Audio(track.url);
      audio.loop = true;
      audio.volume = this.bgmVolume;
      this.bgmHtmlAudio = audio;
      this.bgmPlaying = true;
      const playPromise = audio.play();
      if (playPromise && typeof playPromise.catch === 'function') {
        playPromise.catch(() => {
          if (this.bgmHtmlAudio === audio) {
            this.bgmPlaying = false;
          }
        });
      }
    } catch {
      this.bgmPlaying = false;
    }
  }

  startBgm() {
    if (!this.bgmEnabled) return;
    const ctx = this.ensureContext();
    if (!ctx) return;

    const hasActiveSource =
      Boolean(this.bgmSourceNode) || Boolean(this.bgmHtmlAudio && !this.bgmHtmlAudio.paused);
    if (this.bgmPlaying && hasActiveSource) return;

    this.restartBgmLoop();
  }

  restartBgmLoop() {
    const token = ++this.bgmRequestToken;
    this._stopCurrentBgmNodes(0);

    if (!this.bgmEnabled) {
      this.bgmPlaying = false;
      return;
    }
    const ctx = this.ensureContext();
    if (!ctx) return;

    const track = this.getCurrentTrack();
    if (!track) return;

    // Nếu mở trực tiếp qua giao thức file://, dùng HTMLAudioElement (loop=true)
    if (window.location && window.location.protocol === 'file:') {
      this._startHtmlAudioFallback(track, token);
      return;
    }

    this.bgmPlaying = true;
    this.loadBgmTrackBuffer(track).then((buffer) => {
      if (!this.bgmEnabled || token !== this.bgmRequestToken) return;
      if (!buffer) {
        this._startHtmlAudioFallback(track, token);
        return;
      }

      const liveCtx = this.ensureContext(true);
      if (!liveCtx) return;
      if (!this.bgmMasterGain) {
        this.setupBgmBus(liveCtx);
      }

      const src = liveCtx.createBufferSource();
      src.buffer = buffer;
      src.loop = true;
      const meta = this.bgmLoopMeta[track.id];
      if (meta) {
        src.loopStart = meta.loopStart;
        src.loopEnd = meta.loopEnd;
      }

      src.connect(this.bgmMasterGain);

      const now = liveCtx.currentTime;
      this.bgmMasterGain.gain.cancelScheduledValues(now);
      this.bgmMasterGain.gain.setValueAtTime(0.001, now);
      this.bgmMasterGain.gain.linearRampToValueAtTime(this.bgmVolume, now + 1.1);

      try {
        src.start(0, meta ? meta.loopStart : 0);
        this.bgmSourceNode = src;
        this.bgmPlaying = true;
      } catch {
        this._startHtmlAudioFallback(track, token);
      }

      // Nạp sẵn bài kế tiếp ở nền để bấm đổi bài phát tức thì
      const nextTrack = BGM_TRACKS[(this.currentTrackIndex + 1) % BGM_TRACKS.length];
      if (nextTrack && !this.bgmBuffers[nextTrack.id]) {
        this.loadBgmTrackBuffer(nextTrack);
      }
    });
  }

  stopBgm() {
    this.bgmRequestToken++;
    this.bgmPlaying = false;
    if (this.bgmHtmlAudio) {
      try {
        this.bgmHtmlAudio.pause();
        this.bgmHtmlAudio.src = '';
      } catch {
        // Ignore
      }
      this.bgmHtmlAudio = null;
    }
    if (this.ctx && this.bgmMasterGain) {
      const now = this.ctx.currentTime;
      this.bgmMasterGain.gain.cancelScheduledValues(now);
      this.bgmMasterGain.gain.setValueAtTime(this.bgmMasterGain.gain.value, now);
      this.bgmMasterGain.gain.linearRampToValueAtTime(0.0001, now + 0.35);
      const oldSrc = this.bgmSourceNode;
      this.bgmSourceNode = null;
      if (oldSrc) {
        setTimeout(() => {
          try {
            oldSrc.stop();
            oldSrc.disconnect();
          } catch {
            // Ignore
          }
        }, 380);
      }
    } else {
      this._stopCurrentBgmNodes(0);
    }
  }


  // ==========================================================================
  // GAMEPLAY SOUND EFFECTS (SFX) — 100% FILE GHI ÂM THẬT CC0 (NHÓM 1 + NHÓM 2)
  // ==========================================================================

  _startBufferNode(ctx, buf, key, { volume = 0.65, rate = 1.0, delay = 0, maxDuration = 0 } = {}) {
    if (!this.sfxEnabled || !ctx || !buf) return;
    const now = ctx.currentTime + Math.max(0, delay);
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.playbackRate.setValueAtTime(rate, now);

    const gain = ctx.createGain();
    gain.gain.setValueAtTime(volume, now);
    if (maxDuration > 0) {
      gain.gain.setValueAtTime(volume, now + maxDuration * 0.65);
      gain.gain.exponentialRampToValueAtTime(0.001, now + maxDuration);
    }

    src.connect(gain);
    gain.connect(ctx.destination);

    this.activeSfxSources.add(src);
    src.onended = () => {
      this.activeSfxSources.delete(src);
    };

    const offset = this.sfxOffsets[key] || 0;
    try {
      if (maxDuration > 0) {
        src.start(now, offset, maxDuration + 0.02);
      } else {
        src.start(now, offset);
      }
    } catch {
      this.activeSfxSources.delete(src);
    }
  }

  /**
   * Phát một AudioBuffer CC0 qua Web Audio API (chạy mượt trên cả iOS, Desktop & file://)
   * Không bao giờ rơi về âm thanh tổng hợp bằng code cũ.
   */
  playCardBuffer(key, opts = {}) {
    const ctx = this.sfxContext();
    if (!ctx) return false;
    if (this.bgmEnabled && !this.bgmPlaying) {
      this.startBgm();
    }
    const buf = this.sfxBuffers[key];
    if (buf) {
      this._startBufferNode(ctx, buf, key, opts);
      return true;
    }
    this.decodeSingleCardSfx(key).then((decoded) => {
      if (decoded && this.sfxEnabled) {
        this._startBufferNode(ctx, decoded, key, opts);
      }
    });
    return true;
  }

  /**
   * Nhóm 1.1: Tiếng xào bài (card_shuffle.mp3 - CC0)
   */
  playCardShuffle(volume = 0.68) {
    const rate = 0.97 + Math.random() * 0.06;
    this.playCardBuffer('shuffle', { volume, rate });
  }

  /**
   * Nhóm 1.2: Tiếng chia 1 lá bài (card_deal.mp3 - CC0)
   */
  playCardDeal(volume = 0.56, pitchRate = null) {
    const rate = pitchRate || 0.95 + Math.random() * 0.1;
    this.playCardBuffer('deal', { volume, rate });
  }

  /**
   * Chuỗi tiếng chia nhiều lá bài liên tiếp (dùng đầu hiệp hoặc khi bấm nghe thử)
   */
  playCardDealSequence(count = 5, intervalMs = 68, startDelayMs = 0) {
    if (!this.sfxEnabled) return;
    if (this.dealTimers && this.dealTimers.length > 0) {
      this.dealTimers.forEach((t) => clearTimeout(t));
      this.dealTimers = [];
    }
    for (let i = 0; i < count; i++) {
      const timer = setTimeout(() => {
        if (!this.sfxEnabled) return;
        const rate = 0.94 + (i % 4) * 0.035 + Math.random() * 0.03;
        this.playCardDeal(0.52, rate);
      }, startDelayMs + i * intervalMs);
      this.dealTimers.push(timer);
    }
  }

  /**
   * Tổ hợp Trống Taiko + Chiêng "Tháng X", nối tiếp Xào bài + Chia bài khi bắt đầu ván / sang tháng mới
   */
  playRoundDealIntro() {
    if (!this.sfxEnabled) return;
    this.playMonthIntro();
    const shufTimer = setTimeout(() => {
      if (!this.sfxEnabled) return;
      this.playCardShuffle(0.64);
    }, 320);
    this.dealTimers.push(shufTimer);
    this.playCardDealSequence(5, 68, 720);
  }

  /**
   * Nhóm 1.3: Tiếng lật lá bài (card_flip.mp3 - CC0)
   */
  playCardFlip(volume = 0.6) {
    const rate = 0.96 + Math.random() * 0.08;
    this.playCardBuffer('flip', { volume, rate });
  }

  /**
   * Rà chuột nhẹ qua lá bài trên tay (phiên bản cực êm của tiếng lướt giấy CC0)
   */
  playCardHover() {
    const rate = 1.15 + Math.random() * 0.08;
    this.playCardBuffer('deal', { volume: 0.16, rate });
  }

  /**
   * Nhóm 1.4: Tiếng đập lá bài xuống chiếu ("Pachin!" - card_slap.mp3 CC0)
   */
  playCardSnap(isBright = false) {
    const rate = isBright ? 0.96 : 0.96 + Math.random() * 0.08;
    const vol = isBright ? 0.88 : 0.74;
    this.playCardBuffer('slap', { volume: vol, rate });
  }

  // ==========================================================================
  // NHÓM 2: NHẠC CỤ NHẬT BẢN & HIỆU ỨNG THU ÂM THẬT CC0 (VCSL & KENNEY CC0)
  // ==========================================================================

  /**
   * Nhóm 2.1: Taiko + Chiêng đồng thật khi hiện "Tháng X" / mở đầu hiệp đấu (month_taiko.mp3 CC0)
   */
  playMonthIntro() {
    this.playCardBuffer('month', { volume: 0.9, rate: 1.0 });
  }

  /**
   * Nhóm 2.2: Tiếng đàn Koto khi thành bộ Yaku, phân làm 4 cấp bậc rõ rệt (CC0):
   * - Bậc 1 (yaku_kasu.mp3): Bộ Thường (Kasu / Thập Thảo 1đ)
   * - Bậc 2 (yaku_tanzaku.mp3): Bộ Dải Thơ (Ngũ Đan, Xích Đan, Thanh Đan, Song Đan)
   * - Bậc 3 (yaku_tane.mp3): Bộ Thú & Thưởng Rượu (Trư-Lộc-Điệp, Hoa Kiến Tửu, Nguyệt Kiến Tửu, Ngũ Thú, Tứ Quý)
   * - Bậc 4 (yaku_hikari.mp3): Bộ Quang Tối Thượng (Tam Quang, Vũ Tứ Quang, Tứ Quang, Ngũ Quang)
   */
  resolveYakuSfxKey(yakuOrTier) {
    if (typeof yakuOrTier === 'string') {
      const s = yakuOrTier.toLowerCase();
      if (s === 'kasu' || s === 'yaku_kasu') return 'yaku_kasu';
      if (s === 'tanzaku' || s === 'yaku_tanzaku' || s === 'akatan' || s === 'aotan' || s === 'akatan_aotan') {
        return 'yaku_tanzaku';
      }
      if (s === 'hikari' || s === 'yaku_hikari' || s === 'goko' || s === 'shiko' || s === 'ameshiko' || s === 'sanko') {
        return 'yaku_hikari';
      }
      return 'yaku_tane';
    }
    if (yakuOrTier && typeof yakuOrTier === 'object') {
      const id = String(yakuOrTier.id || '').toLowerCase();
      const cat = String(yakuOrTier.category || '').toLowerCase();
      if (id === 'goko' || id === 'shiko' || id === 'ameshiko' || id === 'sanko' || cat === 'hikari') {
        return 'yaku_hikari';
      }
      if (id === 'akatan_aotan' || id === 'akatan' || id === 'aotan' || id === 'tanzaku' || cat === 'tanzaku') {
        return 'yaku_tanzaku';
      }
      if (id === 'kasu' || cat === 'kasu') {
        return 'yaku_kasu';
      }
      return 'yaku_tane';
    }
    return yakuOrTier === true ? 'yaku_hikari' : 'yaku_tane';
  }

  playYakuKotoGlissando(yakuOrTier = false) {
    const key = this.resolveYakuSfxKey(yakuOrTier);
    const volMap = {
      yaku_kasu: 0.80,
      yaku_tanzaku: 0.85,
      yaku_tane: 0.88,
      yaku_hikari: 0.94
    };
    this.playCardBuffer(key, { volume: volMap[key] || 0.88, rate: 1.0 });
  }

  /**
   * Nhóm 2.3: Tiếng phách gỗ Hyōshigi + trống Taiko thật khi gọi "KOI-KOI!" (koikoi_hyoshigi.mp3 CC0)
   */
  playKoiKoiFanfare() {
    this.playCardBuffer('koikoi', { volume: 0.92, rate: 1.0 });
  }

  /**
   * Mở bảng quyết định Koi-Koi / Shōbu: tiếng giấy lật trầm + phách gỗ nhẹ
   */
  playScrollOpen() {
    this.playCardBuffer('flip', { volume: 0.7, rate: 0.72 });
    setTimeout(() => this.playCardBuffer('click', { volume: 0.5, rate: 0.85 }), 140);
  }

  /**
   * Nhóm 2.4: Tiếng bấm nút giao diện bằng mộc bản/gỗ Nhật thật (ui_click.mp3 CC0)
   */
  playButtonClick() {
    const rate = 0.96 + Math.random() * 0.08;
    this.playCardBuffer('click', { volume: 0.72, rate });
  }

  /**
   * Nhóm 2.5: Tiếng nhận Xu Hoa / đồng xu kim loại & chuông cổ thật (coin_reward.mp3 CC0)
   */
  playCoinReward(coinCount = 5) {
    const rate = coinCount >= 5 ? 1.0 : 1.05;
    this.playCardBuffer('coin', { volume: 0.88, rate });
  }

  /**
   * Celebratory Koto fanfare when declaring Shōbu / Winning a round
   */
  playShobuVictory() {
    this.playYakuKotoGlissando('hikari');
  }

  /**
   * Gacha Omikuji pull & reveal chime (dùng bản thu âm Koto CC0 theo độ hiếm)
   */
  playGachaReveal(isHighRarity = false) {
    this.playCardBuffer(isHighRarity ? 'yaku_hikari' : 'yaku_tanzaku', {
      volume: isHighRarity ? 0.92 : 0.84,
      rate: 1.0
    });
  }

  /**
   * Speaks a character's teasing / pouting / praising line in Japanese (via Web Speech API)
   */
  speakCharacterLine(opponent, lineObj) {
    if (!this.sfxEnabled || !lineObj) return;
    const vp = (opponent && opponent.voiceProfile) || { pitch: 1.1, rate: 1.0 };

    if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
      try {
        window.speechSynthesis.cancel();
        const voices = window.speechSynthesis.getVoices() || [];
        const jpVoice = voices.find((v) => v.lang && v.lang.toLowerCase().startsWith('ja'));
        const viVoice = voices.find((v) => v.lang && v.lang.toLowerCase().startsWith('vi'));

        const utter = new SpeechSynthesisUtterance(
          jpVoice ? lineObj.jp : viVoice ? lineObj.vi : lineObj.jp
        );
        if (jpVoice) {
          utter.voice = jpVoice;
          utter.lang = 'ja-JP';
        } else if (viVoice) {
          utter.voice = viVoice;
          utter.lang = 'vi-VN';
        } else {
          utter.lang = 'ja-JP';
        }
        utter.pitch = vp.pitch || 1.1;
        utter.rate = vp.rate || 1.0;
        utter.volume = 0.9;
        window.speechSynthesis.speak(utter);
      } catch {
        // Ignore TTS errors on restricted browsers
      }
    }
  }
}

export const soundEngine = new SoundEngine();
